// Register shader with UE5
IMPLEMENT_GLOBAL_SHADER(FK3ThermalShader, "/Plugin/KainCosmos/K3Thermal.usf", "K3ThermalCS", SF_Compute);

// Helper function to add pass to render graph
void AddPass_K3Thermal(
    FRDGBuilder& GraphBuilder,
    FRDGTextureRef height_map,
    FRDGTextureRef OutputTexture,
    FIntVector GroupCount
)
{
    FK3ThermalShader::FParameters* Params = GraphBuilder.AllocParameters<FK3ThermalShader::FParameters>();
    // Bind Textures
    Params->height_map = height_map;
    Params->height_mapSampler = TStaticSamplerState<SF_Bilinear, AM_Clamp, AM_Clamp, AM_Clamp>::GetRHI();
    // Bind UAVs
    Params->OutputTexture = GraphBuilder.CreateUAV(OutputTexture);

    FK3ThermalShader::Exec(GraphBuilder, *Params, GroupCount);
}
